1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .p-I { background: #00c8e0 !important; }
27	  .p-O { background: #f0d000 !important; }
28	  .p-T { background: #a040f0 !important; }
29	  .p-S { background: #30c050 !important; }
30	  .p-Z { background: #e03030 !important; }
31	  .p-J { background: #3060f0 !important; }
32	  .p-L { background: #f08c20 !important; }
33	</style>
34	</head>
35	<body>
36	<div class="game">
37	  <div class="board" data-testid="board" id="board"></div>
38	  <div class="side">
39	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
40	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
41	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
42	    <div class="stat"><div class="label">Next</div><div id="next"></div></div>
43	    <div class="help">← → move<br>↑ or X rotate<br>↓ soft drop<br>Space hard drop</div>
44	  </div>
45	</div>
46	<script>
47	(function () {
48	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
49	
50	  // [REQ-001] spawn shapes as [row, col] on the board
51	  var SHAPES = {
52	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
53	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
54	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
55	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
56	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
57	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
58	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
59	  };
60	
61	  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
62	  var BOX = {
63	    I: { size: 4, origin: [-1, 3] },
64	    O: { size: 2, origin: [0, 4] },
65	    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
66	    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
67	  };
68	  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
69	  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
70	  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
71	
72	  var state = {
73	    board: [],      // board[row][col] = letter or null
74	    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }
75	    upcoming: [],
76	    score: 0, level: 1, lines: 0,
77	    status: "running"
78	  };
79	  var timer = null;
80	
81	  var boardEl = document.getElementById("board");
82	  var cellEls = [];
83	  for (var r = 0; r < ROWS; r++) {
84	    cellEls.push([]);
85	    for (var c = 0; c < COLS; c++) {
86	      var el = document.createElement("div");
87	      el.className = "cell";
88	      el.setAttribute("data-testid", "cell");
89	      el.setAttribute("data-row", r);
90	      el.setAttribute("data-col", c);
91	      boardEl.appendChild(el);
92	      cellEls[r].push(el);
93	    }
94	  }
95	
96	  function emptyBoard() {
97	    var b = [];
98	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
99	    return b;
100	  }
101	
102	  function randomLetter() {
103	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
104	  }
105	
106	  function validLetters(queue) {
107	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
108	  }
109	
110	  // [REQ-001] take the next piece from the queue, falling back to random
111	  function takeNext() {
112	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
113	    if (!state.upcoming.length) state.upcoming.push(randomLetter());
114	    return letter;
115	  }
116	
117	  function spawn() {
118	    var type = takeNext();
119	    state.current = {
120	      type: type,
121	      cells: SHAPES[type].map(function (p) { return [p[0], p[1]]; }),
122	      origin: BOX[type].origin.slice(),
123	      lockTicks: 0, lockResets: 0
124	    };
125	  }
126	
127	  function fits(cells) {
128	    return cells.every(function (p) {
129	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
130	    });
131	  }
132	
133	  function canMove(dr, dc) {
134	    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
135	  }
136	
137	  function tryMove(dr, dc) {
138	    if (!state.current || !canMove(dr, dc)) return false;
139	    var cur = state.current;
140	    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
141	    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
142	    if (dr > 0) cur.lockTicks = 0;
143	    return true;
144	  }
145	
146	  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
147	  function tryRotateCW() {
148	    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
149	    var turned = cur.cells.map(function (p) {
150	      var lr = p[0] - o[0], lc = p[1] - o[1];
151	      return [o[0] + lc, o[1] + n - 1 - lr];
152	    });
153	    // a rotation near the top edge is pushed down just enough to stay on the board
154	    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
155	    for (var i = 0; i < KICKS.length; i++) {
156	      var dc = KICKS[i];
157	      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
158	      if (fits(cand)) {
159	        cur.cells = cand;
160	        cur.origin = [o[0] + dr, o[1] + dc];
161	        return true;
162	      }
163	    }
164	    return false;
165	  }
166	
167	  // [REQ-002] sideways move; while resting it restarts the lock delay, at most MAX_LOCK_RESETS times
168	  function shift(dc) {
169	    var resting = !canMove(1, 0);
170	    if (!tryMove(0, dc) || !resting) return;
171	    var cur = state.current;
172	    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
173	  }
174	
175	  // [REQ-001] lock the falling piece and spawn the next one
176	  function lock() {
177	    var cur = state.current;
178	    cur.cells.forEach(function (p) {
179	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
180	    });
181	    spawn();
182	  }
183	
184	  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
185	  function gravityStep() {
186	    if (state.status !== "running") return;
187	    if (!state.current) spawn();
188	    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
189	    render();
190	  }
191	
192	  // [REQ-001] [REQ-002] player actions; hard drop locks at once, with no delay
193	  function input(action) {
194	    if (state.status !== "running" || !state.current) return;
195	    if (action === "left") shift(-1);
196	    else if (action === "right") shift(1);
197	    else if (action === "rotateCW") tryRotateCW();
198	    else if (action === "softDrop") tryMove(1, 0);
199	    else if (action === "hardDrop") { while (tryMove(1, 0)) {} lock(); }
200	    render();
201	  }
202	
203	  // [REQ-001] synchronous render from the real game state
204	  function render() {
205	    var drawn = state.board.map(function (row) { return row.slice(); });
206	    if (state.current) {
207	      state.current.cells.forEach(function (p) {
208	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
209	      });
210	    }
211	    for (var r = 0; r < ROWS; r++) {
212	      for (var c = 0; c < COLS; c++) {
213	        var el = cellEls[r][c], letter = drawn[r][c];
214	        el.className = letter ? "cell p-" + letter : "cell";
215	        el.setAttribute("data-filled", letter ? "true" : "false");
216	        el.setAttribute("data-piece", letter || "");
217	      }
218	    }
219	    document.getElementById("score").textContent = String(state.score);
220	    document.getElementById("level").textContent = String(state.level);
221	    document.getElementById("lines").textContent = String(state.lines);
222	    renderNext();
223	  }
224	
225	  function renderNext() {
226	    var box = document.getElementById("next");
227	    box.innerHTML = "";
228	    state.upcoming.slice(0, 3).forEach(function (type) {
229	      var grid = document.createElement("div");
230	      grid.className = "preview";
231	      var filled = {};
232	      SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
233	      for (var r = 0; r < 2; r++) {
234	        for (var c = 0; c < 4; c++) {
235	          var m = document.createElement("div");
236	          m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
237	          grid.appendChild(m);
238	        }
239	      }
240	      box.appendChild(grid);
241	    });
242	  }
243	
244	  function startTimer() {
245	    if (timer) clearInterval(timer);
246	    timer = setInterval(gravityStep, 1000);
247	  }
248	
249	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
250	  function newGame(queue) {
251	    state.board = emptyBoard();
252	    state.score = 0; state.level = 1; state.lines = 0;
253	    state.status = "running";
254	    state.upcoming = validLetters(queue);
255	    state.current = null;
256	    spawn();
257	    startTimer();
258	    render();
259	  }
260	
261	  // [REQ-001] test control surface
262	  window.__tetris = {
263	    newGame: newGame,
264	    setQueue: function (queue) {
265	      state.upcoming = validLetters(queue);
266	      render();
267	    },
268	    setBoard: function (rows) {
269	      var b = emptyBoard();
270	      for (var r = 0; r < ROWS; r++) {
271	        var line = (rows && rows[r]) || "";
272	        for (var c = 0; c < COLS; c++) {
273	          var ch = line.charAt(c);
274	          b[r][c] = SHAPES[ch] ? ch : null;
275	        }
276	      }
277	      state.board = b;
278	      render();
279	    },
280	    tick: function (n) {
281	      if (n === undefined) n = 1;
282	      for (var i = 0; i < n; i++) gravityStep();
283	    },
284	    input: input,
285	    getBoard: function () {
286	      return state.board.map(function (row) {
287	        return row.map(function (v) { return v || "."; }).join("");
288	      });
289	    },
290	    getState: function () {
291	      return {
292	        current: state.current
293	          ? {
294	              type: state.current.type,
295	              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
296	              lockTicks: state.current.lockTicks,
297	              lockResets: state.current.lockResets
298	            }
299	          : null,
300	        next: state.upcoming.slice(),
301	        score: state.score, level: state.level, lines: state.lines,
302	        status: state.status
303	      };
304	    }
305	  };
306	
307	  document.addEventListener("keydown", function (e) {
308	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop" };
309	    var action = map[e.key];
310	    if (!action) return;
311	    e.preventDefault();
312	    input(action);
313	  });
314	
315	  newGame();
316	})();
317	</script>
318	</body>
319	</html>
