// [REQ-003] remove full rows, drop everything above, count lines and score the clear
function clearLines() {
  var kept = state.board.filter(function (row) { return !row.every(Boolean); });
  var cleared = ROWS - kept.length;
  if (!cleared) return;
  while (kept.length < ROWS) kept.unshift(new Array(COLS).fill(null));
  state.board = kept;
  state.lines += cleared;
  state.score += CLEAR_POINTS[cleared] * state.level;
}

